  'Leeskolom': 'Kolom di lesa',
  'Ware grootte': 'Tamaño real',
  'Pagina-einden gelden alleen op paginabreedte.':
      'E kortamentonan di página ta konta solamente na ancho di página.',
  'Hoe breed de leeskolom in de visuele modus is. Smal leest rustig, breed gebruikt meer van het scherm. Of je op die kolom, op paginabreedte of op het hele venster schrijft, kies je in de werkbalk.':
      'Ki ancho e kolom di lesa ta den e modo visual. Smal ta lesa trankil, hanchu ta usa mas di e pantaya. Si bo ta skirbi riba e kolom ei, na ancho di página òf riba henter e bentana, bo ta skohe den e bara di hèrmènt.',
  'De sprong "{doel}" wijst naar een dia die niet meer bestaat; tijdens het presenteren gebeurt er niets. Kies een andere doeldia.':
      'E salto "{doel}" ta apuntá na un slide ku no ta eksistí mas; durante e presentashon no ta pasa nada. Skohe un otro slide di destino.',
  'In een cirkel': 'Sirkel',
  'Onder elkaar': 'Lista',
  'Categorie': 'Kategoria',
  'Categorie toevoegen': 'Agregá kategoria',
  'Categorie opheffen (blokken blijven behouden)':
      'Kita kategoria (blòkinan ta keda)',
  'Uitleg': 'Splikashon',
  'Een keuzemenu: elk blok springt bij aanklikken naar een andere dia. Typ per blok een label en een uitleg, kies de doeldia en eventueel een afbeelding. Kies de indeling: raster, onder elkaar of in een cirkel. Met categorieën wissel je tijdens het presenteren tussen groepen blokken. Een blok zonder doel is gewone tekst.':
      'Un menú di skoho: kada blòki ta bula pa un otro slide ora bo klik riba dje. Skirbi un label i un splikashon pa kada blòki, skohe e slide di destino i opshonalmente un imagen. Skohe e areglo: kuadrikula, lista òf sirkel. Ku kategorianan bo ta kambia entre gruponan di blòki durante e presentashon. Un blòki sin destino ta teksto normal.',
  'Alleen een lege dia.': 'Solamente un slide bashí.',
  'Hoofdstukken op nieuwe pagina': 'Kapítulo riba página nobo',
  'Elk hoofdstuk begint nu op een nieuwe pagina':
      'Awor kada kapítulo ta kuminsá riba un página nobo',
  'Elk hoofdstuk begon al op een nieuwe pagina':
      'Kada kapítulo tabata kuminsá kaba riba un página nobo',
  'Snijtekens': 'Marka di korta',
  'Alleen in de LaTeX/PDF-export, en alleen met afloop. Vereist het crop-pakket in je TeX-installatie; een browser-afdruk van de HTML-export zet ze niet.':
      'Solamente den e eksportashon LaTeX/PDF, i solamente ku sangrado. Ta rekerí e paket crop den bo instalashon di TeX; imprimí e eksportashon HTML for di un browser no ta pone nan.',
  'Deze paginaopmaak staat in dit document':
      'E formato di página aki ta den e dokumento aki',
  'Deze paginaopmaak komt uit je instellingen':
      'E formato di página aki ta bini for di bo konfigurashon',
  'Paginaopmaak': 'Formato di página',
  'De paginamaat en marges staan nu in dit document; wie het opent krijgt dezelfde pagina. Haal ze eruit om je eigen instelling te laten gelden.':
      'Awor e tamaño di página i e marge ta den e dokumento aki; ken ku habri e ta haña e mesun página. Kita nan pa bo mes konfigurashon apliká.',
  'De paginamaat en marges komen nu uit je instellingen, dus bij een ander kan het document anders uitvallen. Zet ze in het document om dat vast te leggen.':
      'E tamaño di página i e marge ta bini for di bo konfigurashon, pues serka un otro hende e dokumento por parse diferente. Pone nan den e dokumento pa fiha esaki.',
  'Uit het document halen': 'Kita for di dokumento',
  'In dit document vastleggen': 'Warda den e dokumento aki',
