  'Deze afbeelding naar het AI-model sturen?':
      'Manda e imagen aki na e modelo di IA?',
  'De afbeelding gaat ongewijzigd naar': 'E imagen ta bai sin kambio na',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck no ta redaktá nada den un imagen: karanan, teksto riba un potrèt di pantaya i datos na bista ta bai huntu.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'E kontrol di imagen a haña un o mas kara rekonosibel akinan.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Banda di e eksportashon ta keda dos file ku kua un risibidó por kontrolá e redakshonnan.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'ta lista loke a keda afó, sin e balornan mes. E file aki por bai huntu ku e rapòrt.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'ta kontené e yabinan ku kua tur balor redaktá por wòrdu kalkulá bèk. No manda e file aki huntu: e ora ei e redakshon ta anulá. Wardé serka e fuente.',
  'slides': 'slides',
  'Achtergehouden': 'Retené',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Retené: klasifiká mas strikto ku e presentashon',
  '1 slide achtergehouden door haar TLP': '1 lámina retené pa su TLP',
  'slides achtergehouden door hun TLP': 'lámina retené pa nan TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'E slidenan aki no ta bai huntu ora di presentá, eksportá ni den e paket. Halsa e nivel TLP di e presentashon na Info di presentashon pa hiba nan huntu.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Tur lámina ta retené pa nan klasifikashon TLP — no tin nada pa mustra.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Tur lámina ta retené pa nan klasifikashon TLP — no tin nada pa eksportá.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Tur lámina ta pasá over of retené pa nan klasifikashon TLP — no tin nada pa mustra.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Tur lámina ta pasá over of retené pa nan klasifikashon TLP — no tin nada pa eksportá.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'E sifranan di grafiko no a keda wardá — nan ta solamente den e bentana aki:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Den e browser no tin rekuperashon despues di un crash: si bo sera e tab aki, trabou no wardá ta pèrdí. Warda bo presentashon bo mes.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  E base di datos CVE lokal (ta bo ta kuminsá e download): OciDeck ta buska e datos na bulto via api.github.com i e archivo di release ku e adrès ei ta indiká.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Buska CVE (ta pagá pa defekto): si e ta sendé, bo palabra di buskeda ta bai na e spil CVE konfigurá i, si esei no haña nada, na e base di datos Europeo di ENISA i na MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Un vidio di YouTube of Vimeo inkorporá ta karga e reprodukdó for di e servisio ei.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Den e browser: si e browser ta nenga di haña un adrès direktamente, OciDeck ta purba atrobe via e server for di kua e app a bini; e ora ei e adrès ta yega e server ei.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'E retirada no a keda grabá. Ora bo start di nobo, bo konsentimentu ta bálido atrobe.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Un enkabesamentu di sekshon ku ta anunsiá un parti nobo di e presentashon. Tenele kòrtiku. Agregá un imágen di fondo for di e biblioteka di imágen.',
  'Bronnen doorzoeken…': 'Ta buska den e fuentenan…',
  'Niet doorzocht': 'No buska',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'E kontrol aki no ta kore den e version web: detekshon di kara ta rekerí un biblioteka di sistema ku e browser no tin. Usa e version desktop pa chek kara den imagen.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'E token mester tin akseso di lesa i skirbi na e repositorio. Gitea i Forgejo no tin buskeda na servidó; OciDeck ta buska lokalmente.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'E token mester tin e scope repo (òf detayá: Contents lesa i skirbi).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'E token mester tin read_repository, write_repository i read_api. Buskeda na servidó ta rekerí Advanced òf Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Buskeda rápido riba servidó — pa motibu di retraso di indeksashon, un dek net kambiá por falta.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Media no ta keda warda den un simpel archivo .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Imagen, video i audio ku bo a skohe den e tab aki ta biba solamente den memoria. Un simpel archivo .md no ta warda nan — nan ta perdí ora bo habri e atrobe. Eksportá komo un paket .ocideck pa hiba e media ku bo.',
  'Media verwijderd om privacyredenen':
      'Media kitá kitá pa motibu di privacidat',
