  'Certificaat vertrouwen?': 'Konfia e sertifikado aki?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'E sertifikado di e servidor aki no ta firmá pa un emisor rekonosí. Esei ta normal pa un servidor propio, pero ta tambe kon un konekshon interseptá ta parse.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Kompará e wela di dede aki bou ku loke bo servidor mes ta mustra. Si nan ta igual, bo ta papia ku e mashin korekto.',
  'Uitgegeven aan': 'Emití na',
  'Uitgegeven door': 'Emití pa',
  'Geldig tot': 'Bálido te',
  'Vingerafdruk (SHA-256)': 'Wela di dede (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Solamente e sertifikado aki ta konfiá. Si e servidor kambi\'é despues, OciDeck lo puntra atrobe.',
  'Vertrouwen': 'Konfia',
  'Certificaat bekijken': 'Wak sertifikado',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'E lugánan kaminda bo ta warda i buska bo presentashonnan — kartafolionan riba e kòmpiuter aki, servidónan WebDAV, bucket di S3 i repositorionan di git meskla. Lastra nan den e òrdu ku bo ke: esun di ariba di un tipo ta konta komo standard.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Almasenamentu S3: ora bo konektá ku un bucket, e endpoint, e nòmber di e bucket i bo yabi di akseso ta keda wardá (e yabi sekreto sigur den e yaberu di bo sistema) i e presentashonnan ku bo ta habri òf warda ta wòrdu mandá pa e servisio di almasenamentu ei.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Almasenamentu Git: ora bo konektá ku un repositorio, bo token di akseso ta keda wardá (sigur den e yaberu di bo sistema) i e presentashonnan ku bo ta warda ta wòrdu mandá pa e servidó ei komo commit. Un kopia di trabou di e repositorio ta keda sin sifrá riba e aparato aki.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Pa e idioma di e presentashon aki ta falta nòmber di malesa. Religion, opinion polítiko i término sindikal sí ta wòrdu rekonosí, i patronchi ku sifra di kontrol (BSN, IBAN, pasaporte) semper ta funshoná — ma no konta ku deteshon di un diagnóstiko.',
  'niet getest': 'no testá',
  'Werkte op': 'A funshoná riba',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Bo ta logiá aden, pero bo no tin akseso aki. Bo kontraseña no ta e problema — pidi e administrador derecho riba e karpeta aki.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Bo token ta bálido, pero no tin mag pa esaki. Dun\'é mas derecho, of warda si e forge ta pone un límite.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'E token ta bálido, pero no tin mag pa esaki — dun\'é mas derecho riba e repositorio.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Logiá aden, pero sin akseso — bo kontraseña no ta e problema. Pidi derecho riba e karpeta aki.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Esaki ta parse un URL DAV kompleto. Ku Nextcloud, OciDeck ta deriva e kaminda su mes — aki solamente e servidor ta pertenesé.',
  'Overnemen': 'Apliká',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV no ta konfigurá (bon) — kontrolá e datos di servidor na Konfigurashon → Almasenamentu.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'E repositorio git no ta konfigurá (bon) — kontrolá servidor, doño i repositorio na Konfigurashon → Almasenamentu.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'E nòmber di servidor di e forge no ta eksistí, of no por wòrdu buskí. Kontrolá e URL di servidor pa un eror di tipeo.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'E forge aki tin un adrès privá of di LAN. Marké e komo konfiá interno na Konfigurashon → Almasenamentu.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'E forge no ta alkansabel — kontrolá bo konekshon i e URL di servidor.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Login na e forge a faya. Kontrolá bo token: e tin mester di derecho di lesa e repositorio, i di skirbi pa warda.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'No hañá den e repositorio — of bo token no por mir\'é.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'E forge a duna un eror. Purba atrobe despues.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'E adrès aki no ta kontestá manera un forge. E tipo di forge na Konfigurashon → Almasenamentu ta korekto?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Konfigurá promé un servidor WebDAV na Konfigurashon → Almasenamentu.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Nesesario ora e forge ta kore riba un red privá of di kas. Sin e bandera aki e kontrol di siguridat ta rechasá un adrès privá.',
  'Vul server-URL, eigenaar en repository in':
      'Yena URL di servidor, doño i repositorio',
