  'Privacy blokkeert export': 'Privasidat ta blokia eksportashon',
  'privacybevinding(en) zonder keuze': 'hayasgo(nan) di privasidat sin skoho',
  'Persoonsgegevens, bijzondere gegevens en geheimen in de tekst':
      'Datos personal, datos spesial i sekreto den e teksto',
  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Slides, notanan, tabelnan, kódigo, kaminda di archivo i URL ta wòrdu buská riba e aparato aki pa number identifikadó, datos finansiero, datos di kontakto, identifikadó digital, sekreto, datos personal spesial (GDPR art. 9/10), datos na masa i lek di metadata.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Solamente un resultado sigur ta advertí; probabel i posibel ta keda informativo. Un regla apagá no ta dispará niun kaminda.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'No chequeá: datos personal, datos spesial i sekreto. E kontròl di privasidat ta apagá na Seguridat.',
  'Op deze slide': 'Riba e slide aki',
  'Tijdens presenteren': 'Durante presentashon',
  'Classificatie en privacy': 'Klasifikashon i privacidat',
  'Logo tonen': 'Mustra logo',
  'Footer tonen': 'Mustra pia di página',
  'Tabel bewerkbaar': 'Tabel editabel',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Ta laga bo kambia e tabel dilanti di e públiko durante presentashon. Ta pagá pa default.',
  'Automatisch doorgaan': 'Sigui outomátikamente',
  'Persoonsgegevens': 'Datos personal',
  'Wijzigen': 'Kambia',
  'Automatisch afspelen': 'Toka outomátikamente',
  'Melden': 'Reportá',
  'Geaccepteerd': 'Aseptá',
  'Gewaarschuwd': 'Advertí',
  'Weggelaten': 'Kitá',
  'Bewerkbaar': 'Editabel',
  'De privacycontrole': 'E kontrol di privacidat',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck ta lesa bo slides pa datos ku por ta sensitivo pa privacidat: number di identifikashon, datos di kontakto, number di telefon, kuenta di banko, yabi i kontraseña, i datos personal spesial. Tur esaki ta pasa kompletamente riba e aparato aki: nada no ta wòrdu mandá, i e balor hañá no ta aparesé den ningun mensahe.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'E kontrol no ta garantisá ku tur kos ta wòrdu hañá; e ta redusí e chèns ku datos personal ta lek afó sin ku bo ke.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Teksto den imágen ta keda pafó di bista, archivo lombrá no ta wòrdu habri, i ningun scanner no ta rekonosé datos sin un patronchi rekonosibel. Un slide sin mensahe ta un slide kaminda *nos* no a haña nada, no un slide di kua ta konstá ku no tin nada aden. Loke bo ta kompartí ta keda bo desishon i bo responsabilidat.',
  'telefoonnummer': 'number di telefon',
  'Voor wie is deze export?': 'Pa ken e eksportashon aki ta?',
  'Volledig': 'Kompleto',
  'Geredigeerd': 'Redaktá',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Pa e kliente òf ouditor: solamente loke bo a pone riba "laga afó" ta wòrdu kitá. E resto ta keda legibel, pa un tersero por verifiká e hayasgonan.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Pa e sírkulo mas hancho: tur loke e kontròl ta haña ta wòrdu kitá, tambe riba slidenan ku bo a aseptá. E file ta haña "-geredigeerd" den su nòmber.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tabel ku datos personal (fila×kolom)',
  'massa-persoonsgegevens op één slide': 'datos personal na masa riba un slide',
  'gebruikerspad met een naam erin': 'kaminda di usuario ku un nòmber aden',
  'toegangstoken in een link': 'token di akseso den un link',
  'persoonsgegeven in een link': 'dato personal den un link',
  'deellink met ingebakken toegang':
      'link di kompartimentu ku akseso inkorporá',
  'e-mailadres in een link': 'adres di e-mail den un link',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'imagen inkorporá — nos no por wak paden',
  'Je eigen gegevens': 'Bo mes datos',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Un pa liña: bo nòmber, adres di e-mail, number di telefòn òf e dominio di bo organisashon. Loke ta pará aki no ta wòrdu reportá ni redaktá — ta e remitente, no un hayasgo. Un dominio (example.org) ta kubri tur adres bou di dje.',
  'Bij onafgehandelde persoonsgegevens': 'Ku datos personal no resolví',
  'Export afgebroken vanwege privacybevindingen.':
      'Eksportashon kanselá pa motibu di hayasgo di privasidat.',
  'Export blokkeren': 'Blokeá eksportashon',
  'Export geblokkeerd': 'Eksportashon blokeá',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Eksportashon blokeá: e presentashon aki tin datos personal ku ainda no a tuma un desishon riba dje.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
